Which sketch shows $y=x(x-3)(x+3)$?
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\begin{scope}[shift={(0,0)},scale=0.6]
\draw[->] (-4.6,0)--(4.6,0);
\draw[->] (0,-2.6)--(0,2.6);
\draw[thick,blue,<->,domain=-3.6:3.6,smooth,variable=\x] plot ({\x},{0.14*\x*(\x-3)*(\x+3)});
\node[below,font=\scriptsize] at (-3,-0.15) {$-3$};
\node[below,font=\scriptsize] at (3,-0.15) {$3$};
\node at (-3.9,2.1) {$A$};
\end{scope}
\begin{scope}[shift={(7.5,0)},scale=0.6]
\draw[->] (-4.6,0)--(4.6,0);
\draw[->] (0,-2.6)--(0,2.6);
\draw[thick,blue,<->,domain=-3.6:3.6,smooth,variable=\x] plot ({\x},{-0.14*\x*(\x-3)*(\x+3)});
\node[below,font=\scriptsize] at (-3,-0.15) {$-3$};
\node[below,font=\scriptsize] at (3,-0.15) {$3$};
\node at (-3.9,2.1) {$B$};
\end{scope}
\begin{scope}[shift={(0,-4.2)},scale=0.6]
\draw[->] (-4.9,0)--(4.9,0);
\draw[->] (0,-2.6)--(0,2.6);
\draw[thick,blue,<->,domain=-4.36:4.36,smooth,variable=\x] plot ({\x},{0.20*(\x*\x-9)});
\node[below,font=\scriptsize] at (-3,-0.15) {$-3$};
\node[below,font=\scriptsize] at (3,-0.15) {$3$};
\node at (-4.2,2.1) {$C$};
\end{scope}
\begin{scope}[shift={(7.5,-4.2)},scale=0.6]
\draw[->] (-5.2,0)--(3.6,0);
\draw[->] (0,-2.6)--(0,2.6);
\draw[thick,blue,<->,domain=-4.60:2.90,smooth,variable=\x] plot ({\x},{0.11*\x*(\x-2)*(\x+4)});
\node[below,font=\scriptsize] at (-4,-0.15) {$-4$};
\node[below,font=\scriptsize] at (2,-0.15) {$2$};
\node at (-4.5,2.1) {$D$};
\end{scope}
\end{tikzpicture}
[/tikz]

